parameters.func:
=// Validate the packet against _workspace/handoff/schemas/packet-n8n.schema.json
const fs = require('fs');
const path = require('path');
const wsPath = process.env.HOME + '/Desktop/meta/n8n/_workspace';
try {
  const schema = JSON.parse(fs.readFileSync(path.join(wsPath, 'handoff/schemas/packet-n8n.schema.json'), 'utf8'));
  // Basic validation: check required fields exist
  const required = schema.required || [];
  for (const field of required) {
    if (!packet[field]) throw new Error(`Missing required field: ${field}`);
  }
  return { json: { valid: true, packet } };
} catch(e) {
  throw new Error('Schema validation failed: ' + e.message);
}

=// Compile the human-readable resume prompt
const p = $json.packet;
return {
  json: {
    resume_command: `/n8n-loop resume from _workspace/HANDOFF.md (branch ${p.branch})`,
    active_objective: p.active_objective,
    current_item: p.current_task_id,
    drift_status: p.drift_status,
    verify_commands: [`git -C ${process.env.HOME}/Desktop/meta/n8n status`],
    next_step: p.next_command
  }
}

=// Write reset loop_state.md
const fs = require('fs');
const path = require('path');
const wsPath = process.env.HOME + '/Desktop/meta/n8n/_workspace';
const loopState = {
  cycles_this_session: 0,
  cycles_total: parseInt(fs.readFileSync(path.join(wsPath, 'loop_state.md'), 'utf8')?.match(/cycles_total=(\d+)/)?.[1] || '0') + ($json.total || 0),
  cycle_budget: 3,
  last_item: $json.current_item,
  status: 'resumed',
  apply_mode: false
};
fs.writeFileSync(path.join(wsPath, 'loop_state.md'), Object.entries(loopState).map(([k,v]) => `${k}=${v}`).join('\n'));
return { json: { cycles_reset: true } };

=// Produce _workspace/HANDOFF.md for human readability
const fs = require('fs');
const path = require('path');
const wsPath = process.env.HOME + '/Desktop/meta/n8n/_workspace';
const p = $json.packet;
const lines = [
  `# n8n-loop HANDOFF — ${new Date().toISOString()}`,
  `## Repo & branch   — ~/Desktop/meta/n8n @ ${p.branch}`,
  `## Backlog          — ${p.active_objective} (task: ${p.current_task_id})`,
  `## Drift status     — ${p.drift_status}`,
  `## Next command     — ${p.next_command}`,
  `## Verify-on-resume — git status clean + scoped build`
];
fs.writeFileSync(path.join(wsPath, 'HANDOFF.md'), lines.join('\n'));
return { json: { checkpoint_written: true } };

